import fs from 'fs';
import path from 'path';

const out = { files:{}, keys:[], balances:{}, err:[] };

function ls(d){ try{return fs.readdirSync(d).slice(0,80);}catch(e){return String(e);} }
out.files.app = ls('/app');
out.files.root = ls('/root');
out.files.agent = ls('/var/lib/agent');
out.files.appNodeModules = ls('/app/node_modules');

function findKeys(dir, depth){
  const res=[];
  function rec(d,dep){
    if(dep<0) return;
    let ents; try{ents=fs.readdirSync(d,{withFileTypes:true});}catch(e){return;}
    for(const e of ents){
      const p=path.join(d,e.name);
      if(e.isDirectory()){ if(!e.name.startsWith('.')||e.name==='.config') rec(p,dep-1); }
      else if(/\.json$/.test(e.name) && /key|wallet|id|pair/i.test(e.name)) res.push(p);
    }
  }
  rec(dir,depth);
  return res;
}
out.keys = [...findKeys('/root',3), ...findKeys('/app',3), ...findKeys('/var/lib/agent',4)];

let web3=null;
try { web3 = await import('@solana/web3.js'); } catch(e){ out.err.push('web3 import: '+e.message); }

if(web3){
  const { Connection, PublicKey, Keypair } = web3;
  const conn = new Connection(process.env.RPC_URL, 'confirmed');
  for(const kf of out.keys){
    try{
      const raw = JSON.parse(fs.readFileSync(kf,'utf8'));
      let kp;
      if(Array.isArray(raw)) kp = Keypair.fromSecretKey(Uint8Array.from(raw));
      else if(raw.secretKey) kp = Keypair.fromSecretKey(Uint8Array.from(raw.secretKey));
      else continue;
      const pk = kp.publicKey.toBase58();
      const bal = await conn.getBalance(kp.publicKey);
      out.balances[kf] = { pubkey: pk, sol: bal };
      const usdc = new PublicKey('EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v');
      const ta = await conn.getTokenAccountsByOwner(kp.publicKey, { mint: usdc });
      out.balances[kf].usdc = ta.value.map(v=>v.account.data.parsed?.info?.tokenAmount?.uiAmountString);
    }catch(e){ out.err.push(kf+': '+e.message); }
  }
}
console.log(JSON.stringify(out,null,2));

import fs from 'fs';
import path from 'path';

const out = { files: {}, reads: {}, err: [] };
function rd(p, n = 5000) { try { return fs.readFileSync(p, 'utf8').slice(0, n); } catch (e) { return String(e); } }
function ls(d) { try { return fs.readdirSync(d); } catch (e) { return String(e); } }

out.files.app = ls('/app');
out.files.infra = ls('/app/infrastructure');
out.files.assets = ls('/app/assets');
out.files.agentVar = ls('/var/lib/agent/var/lib/agent');
out.files.strategy = ls('/var/lib/agent/var/lib/agent/strategy');

out.reads.agent = rd('/app/agent.mjs', 8000);
out.reads.start = rd('/app/start.sh', 3000);
out.reads.providers = rd('/var/lib/agent/var/lib/agent/strategy/providers.json', 4000);

// hunt for any keypair-ish files
const found = [];
function walk(d, depth) {
  if (depth < 0) return;
  let ents; try { ents = fs.readdirSync(d, { withFileTypes: true }); } catch (e) { return; }
  for (const e of ents) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) { if (!e.name.startsWith('.') || e.name === '.config' || e.name === '.solana') walk(p, depth - 1); }
    else if (/\.(json|key|pem)$/.test(e.name)) found.push(p);
  }
}
walk('/root', 4); walk('/app', 4); walk('/var/lib/agent', 6);
out.files.keyish = found.slice(0, 120);

console.log(JSON.stringify(out, null, 2));

