const RPC = process.env.RPC_URL;
const curves = [
  "46YFGQB8kq74YTK7xXbuN7SjBPacs1mMbUCbNYyi7WSr",
  "2RWmwiUSNMkgMHtMs6vK5wZmDdmEiiGaaZv8xX2iV87d",
  "HB5vfWwpkwB5DoLQgZwALkFRYJbsLcxad95vB41FeiSg"
];
async function rpc(method, params){
  const r = await fetch(RPC, {method:"POST", headers:{"content-type":"application/json"},
    body: JSON.stringify({jsonrpc:"2.0", id:1, method, params})});
  return await r.json();
}
const out = { curves:{}, pumpProgram:null, err:[] };
for (const c of curves){
  try {
    const info = await rpc("getAccountInfo", [c, {encoding:"base64"}]);
    out.curves[c] = info.result?.value ? {exists:true, owner: info.result.value.owner, len: info.result.value.data[0].length} : {exists:false};
  } catch(e){ out.err.push(c+": "+e.message); }
}
// check pump program id
try {
  const p = await rpc("getAccountInfo", ["6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P", {encoding:"base64"}]);
  out.pumpProgram = p.result?.value ? {exists:true, owner:p.result.value.owner} : {exists:false};
} catch(e){ out.err.push("prog: "+e.message); }
console.log(JSON.stringify(out,null,2));

const RPC = process.env.RPC_URL;
const out = { env: {}, pubkeys: [], wallets: {}, err: [] };
for (const [k, v] of Object.entries(process.env)) {
  if (/KEY|WALLET|PUB|ADDR|MINT|RPC|SOL|USDC|AGENT|OWNER|PAY/i.test(k)) out.env[k] = String(v).slice(0, 120);
}
const b58 = /[1-9A-HJ-NP-Za-km-z]{32,44}/g;
const cands = new Set();
for (const v of Object.values(process.env)) {
  if (typeof v !== 'string') continue;
  const m = v.match(b58); if (m) m.forEach(x => cands.add(x));
}
out.pubkeys = [...cands];
async function rpc(method, params) {
  const r = await fetch(RPC, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }) });
  return r.json();
}
for (const pk of out.pubkeys) {
  try {
    const bal = await rpc('getBalance', [pk]);
    if (bal.result) {
      const ta = await rpc('getTokenAccountsByOwner', [pk, { programId: 'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA' }, { encoding: 'jsonParsed' }]);
      out.wallets[pk] = { sol: bal.result.value, accounts: (ta.result?.value || []).map(v => ({ mint: v.account.data.parsed.info.mint, amt: v.account.data.parsed.info.tokenAmount.uiAmountString })) };
    }
  } catch (e) { out.err.push(pk + ': ' + e.message); }
}
console.log(JSON.stringify(out, null, 2));

const RPC = process.env.RPC || "https://api.mainnet-beta.solana.com";
const mints = [
  "6hcFSm22yz49Q4cdVxootAU1VgtjwNFcJ7rXXcNG3NQf",
  "Bastkf9yPT4pP52iBRYkD4QuuEM1eYuwZQD8Z1ChmnyY",
  "5bjyN58zKjkN1HxJSp4uij4jRczaBzSUypemq1M4j5Co",
  "EfybJoLw7fvSNhrJKWmxAB9Mf6hPkaHVCacHsmJChspF"
];
async function rpc(method, params) {
  const r = await fetch(RPC, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params })
  });
  return r.json();
}
for (const m of mints) {
  const j = await rpc("getAccountInfo", [m, { encoding: "base64" }]);
  const v = j.result && j.result.value;
  console.log(m, v ? ("EXISTS owner=" + v.owner + " lamports=" + v.lamports) : "NULL");
}
// also check pump program id presence
const prog = await rpc("getAccountInfo", ["6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P", { encoding: "base64" }]);
console.log("pumpProgram", prog.result && prog.result.value ? "EXISTS" : "NULL");

const RPC = process.env.RPC || "https://api.mainnet-beta.solana.com";
const envKeys = Object.keys(process.env);
console.log("ENV_KEYS:", envKeys.filter(k => /WALL|PUB|KEY|ADDR|SOL|MINT|RPC|AGENT/i.test(k)).join(","));
for (const k of envKeys) {
  if (/WALLET|PUBKEY|ADDRESS|_ADDR|OWNER/i.test(k)) console.log("ENV", k, "=", process.env[k]);
}
async function rpc(method, params) {
  const r = await fetch(RPC, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params })
  });
  return r.json();
}
// rent requirements for a pump create_v2
const sizes = [["mint", 82], ["bondingCurve", 57], ["metadata", 679], ["ata", 165]];
let total = 0;
for (const [name, size] of sizes) {
  const j = await rpc("getMinimumBalanceForRentExemption", [size]);
  const v = j.result;
  console.log("rent", name, size, v);
  if (typeof v === "number") total += v;
}
console.log("TOTAL_RENT_LAMPORTS", total, "=", (total / 1e9).toFixed(6), "SOL");
// try to find wallet balance
const cand = envKeys.filter(k => /WALLET|PUBKEY|ADDRESS|_ADDR|OWNER/i.test(k)).map(k => process.env[k]).filter(v => typeof v === "string" && v.length > 30);
for (const w of cand) {
  const j = await rpc("getBalance", [w]);
  console.log("balance", w, JSON.stringify(j.result));
}

